const theatreSource='https://rusdram.org/posters';
function theatreText(html:string){return html.replace(/<[^>]*>/g,' ').replace(/&quot;/g,'"').replace(/&#39;|&apos;/g,"'").replace(/&nbsp;/g,' ').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim()}
function theatreLink(value:string,image=false){if(!value.trim())return '';try{const u=new URL(value,theatreSource);return u.protocol==='https:'&&(u.hostname==='rusdram.org'||image&&u.hostname==='ucarecdn.com')?u.href:''}catch{return ''}}
export function parseTheatre(html:string,now=Date.now()){
 const months=['янв','фев','мар','апр','май','июн','июл','авг','сен','окт','ноя','дек'];const current=new Date(now+10800000),year=current.getUTCFullYear();const events:any[]=[];
 for(const match of html.matchAll(/<article\b[^>]*>([\s\S]*?)<\/article>/gi)){
  const block=match[1],title=theatreText(block.match(/<h2\b[^>]*>([\s\S]*?)<\/h2>/i)?.[1]||'');
  const href=block.match(/href="([^"<>]*\/theater\/performs\/[^"<>]+)"/i)?.[1],image=theatreLink(block.match(/<img\b[^>]*src="([^"<>]+)"/i)?.[1]||'',true);
  const before=block.split(/<h2\b/i)[0],parts=Array.from(before.matchAll(/<p\b[^>]*>([\s\S]*?)<\/p>/gi),m=>theatreText(m[1]));const mi=parts.findIndex(p=>months.includes(p.toLowerCase()));if(mi<1)continue;
  const month=months.indexOf(parts[mi].toLowerCase()),day=Number(parts[mi-1]),time=parts[mi+1];if(!/^\d{2}:\d{2}$/.test(time)||day<1||day>31)continue;
  const eventYear=month<current.getUTCMonth()-6?year+1:year;const date=`${eventYear}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}T${time}:00+03:00`;const timestamp=Date.parse(date);
  const url=theatreLink(href||'');if(!title||!url||!image||!Number.isFinite(timestamp)||timestamp<now)continue;
  const tail=block.split(/<\/h2>/i)[1]||'',copy=tail.split(/Состав/)[0];const description=Array.from(copy.matchAll(/<p\b[^>]*>([\s\S]*?)<\/p>/gi),m=>theatreText(m[1])).filter(Boolean).join(' · ').slice(0,550);
  events.push({title,url,image,date,timestamp,description,buy:theatreLink(block.match(/href="([^"<>]*\/buy\/[^"<>]+)"/i)?.[1]||href||''),age:parts.find(p=>/^\d+\+$/.test(p))||''});
 }
 return events.sort((a,b)=>a.timestamp-b.timestamp).slice(0,60)
}
async function theatreFeed(env:Env){
 const now=Date.now(),row=await env.DB.prepare("SELECT value FROM settings WHERE key='rusdram_feed'").first<any>();let saved:any=null;try{saved=row?JSON.parse(row.value):null}catch{}
 const output=(data:any,stale=false)=>json({source:theatreSource,updatedAt:data.updatedAt,stale,events:data.events.filter((e:any)=>e.timestamp>=Date.now())});
 if(saved&&now-saved.checkedAt<900000&&now-saved.updatedAt<86400000)return output(saved,!!saved.stale);
 try{const response=await fetch(theatreSource,{signal:AbortSignal.timeout(15000),headers:{Accept:'text/html'}});if(!response.ok)throw new Error('upstream');const html=await response.text();if(html.length>3000000)throw new Error('size');const events=parseTheatre(html,now);if(!events.length)throw new Error('empty');const data={events,updatedAt:now,checkedAt:now,stale:false};await env.DB.prepare("INSERT INTO settings(key,value) VALUES('rusdram_feed',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value").bind(JSON.stringify(data)).run();return output(data)}
 catch{if(saved&&now-saved.updatedAt<86400000){saved.checkedAt=now;saved.stale=true;await env.DB.prepare("UPDATE settings SET value=? WHERE key='rusdram_feed'").bind(JSON.stringify(saved)).run();return output(saved,true)}return json({source:theatreSource,events:[],unavailable:true,updatedAt:null})}
}
async function admin(env:Env,id:string,email:string){if(!id||!email||email.toLowerCase()!==env.SITE_OWNER_EMAIL?.toLowerCase())return false;await env.DB.prepare('INSERT OR IGNORE INTO settings (key,value) VALUES (?,?)').bind('owner',id).run();return (await env.DB.prepare('SELECT value FROM settings WHERE key=?').bind('owner').first<{value:string}>())?.value===id}
const staffRoles=['admin','dispatcher','editor','observer'] as const;
type StaffRole=typeof staffRoles[number];
async function telegramStaffRole(env:Env,id:string):Promise<StaffRole|''>{if(!id.startsWith('tg:'))return '';const row=await env.DB.prepare("SELECT body FROM records WHERE id=? AND kind='staff-grant' AND owner=?").bind('staff-grant:'+id,id).first<any>();if(!row)return '';try{const role=JSON.parse(row.body).role as StaffRole;return staffRoles.includes(role)?role:''}catch{return ''}}
async function telegramStaff(env:Env){const rows=await env.DB.prepare(`SELECT identity.owner AS id,identity.body AS identity,identity.updated AS seen,profile.body AS profile,grant.body AS grant
 FROM records identity
 LEFT JOIN records profile ON profile.id='profile:'||identity.owner AND profile.kind='profile'
 LEFT JOIN records grant ON grant.id='staff-grant:'||identity.owner AND grant.kind='staff-grant'
 WHERE identity.kind='tg-identity' ORDER BY identity.updated DESC LIMIT 1000`).all<any>();return rows.results.map((row:any)=>{const identity=JSON.parse(row.identity||'{}'),profile=JSON.parse(row.profile||'{}'),grant=JSON.parse(row.grant||'{}'),role=grant.role as StaffRole;return {id:row.id,name:profile.name||identity.name||'Пользователь Telegram',username:identity.username||'',avatar:profile.avatar||identity.photo||'',role:staffRoles.includes(role)?role:'',seenAt:row.seen}})}
